<script>
import BaseComponent from '@primevue/core/basecomponent';
import ScrollAreaScrollbarStyle from 'primevue/scrollareascrollbar/style';

export default {
    name: 'BaseScrollAreaScrollbar',
    extends: BaseComponent,
    props: {
        orientation: {
            type: String,
            default: 'vertical'
        },
        as: {
            type: [String, Object],
            default: 'DIV'
        },
        asChild: {
            type: Boolean,
            default: false
        }
    },
    style: ScrollAreaScrollbarStyle,
    provide() {
        return {
            $pcScrollAreaScrollbar: this,
            $parentInstance: this
        };
    }
};
</script>
